import { Link, useNavigate } from "react-router-dom";

export default function Dashboard() {

const navigate = useNavigate();

const user = JSON.parse(
localStorage.getItem("user")
);

const logout = () => {

localStorage.removeItem("user");

alert("Logout Successful");

navigate("/login");

};

const cards = [

{

title:"👤 Profile",

path:"/profile",

color:"#6366f1"

},

{

title:"📚 Courses",

path:"/courses",

color:"#8b5cf6"

},

{

title:"📝 Assignments",

path:"/assignments",

color:"#06b6d4"

},

{

title:"👨‍🎓 Students",

path:"/students",

color:"#10b981"

},

{

title:"⚙️ Settings",

path:"/settings",

color:"#ef4444"

}

];

return(

<div

style={{

minHeight:"100vh",

background:

"linear-gradient(135deg,#0f172a,#1e293b)",

padding:"40px",

color:"white"

}}

>

<div style={{textAlign:"center"}}>

<h1>

RBAC Dashboard

</h1>

<h2>

Welcome

{user?.name}

</h2>

<h3>

Email :

{user?.email}

</h3>

<h3>

Role :

{user?.role}

</h3>

<button

onClick={logout}

style={{

padding:"10px 20px",

background:"red",

color:"white",

border:"none",

borderRadius:"8px",

cursor:"pointer",

marginTop:"15px"

}}

>

Logout

</button>

</div>



<div

style={{

display:"grid",

gridTemplateColumns:

"repeat(auto-fit,minmax(250px,1fr))",

gap:"25px",

marginTop:"50px"

}}

>

{

cards.map(

(card,index)=>(

<Link

key={index}

to={card.path}

style={{

textDecoration:"none"

}}

>

<div

style={{

background:

card.color,

padding:"30px",

borderRadius:"20px",

color:"white",

textAlign:"center",

cursor:"pointer"

}}

>

<h2>

{card.title}

</h2>

<p>

Open

{card.title}

</p>

</div>

</Link>

)

)

}

</div>

</div>

)

}
